use std::ops::Deref;

struct MyBox<T>(T);

impl<T> Deref for MyBox<T> {
    type Target = T;
    fn deref(&self) -> &T { &self.0 }
}

fn greet(name: &str) { println!("hello {name}"); }

let boxed = MyBox(String::from("ada"));
greet(&boxed); // &MyBox<String> -> &String -> &str

